}

table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 0.75rem;
}

th,
td {
  padding: 0.5rem;
  border-bottom: 1px solid #e3e7ee;
  text-align: left;
}

th {
  font-size: 0.85rem;
  color: #555;
  background: #f0f3f8;
}

th.sortable {
