assert.deepEqual(monthRange('2026-02'), { from: '2026-02-01', to: '2026-02-28' });

// recurring
const m = expandRecurring({ date: '2026-01-31', description: 'rent', amount: -900, category: 'Home', every: 'month' }, '2026-04-30');
assert.deepEqual(m.map(x => x.date), ['2026-01-31', '2026-02-28', '2026-03-31', '2026-04-30']);
assert.deepEqual(m[0], { date: '2026-01-31', description: 'rent', amount: -900, category: 'Home' });
const w = expandRecurring({ date: '2026-12-25', description: 'x', amount: -1, category: 'c', every: 'week' }, '2027-01-08');
assert.deepEqual(w.map(x => x.date), ['2026-12-25', '2027-01-01', '2027-01-08']);
assert.deepEqual(expandRecurring({ date: '2026-02-01', description: 'x', amount: 1, category: 'c', every: 'month' }, '2026-01-01'), []);
const y = expandRecurring({ date: '2024-11-30', description: 'x', amount: 1, category: 'c', every: 'month' }, '2025-02-28');
assert.deepEqual(y.map(x => x.date), ['2024-11-30', '2024-12-30', '2025-01-30', '2025-02-28']);

// budgets
